/** @type {import('@stryker-mutator/api/core').PartialStrykerOptions} */
export default {
  // Use Vitest as the test runner.
  testRunner: "vitest",
  // Explicit modules also work with pnpm's isolated dependency layout.
  plugins: ["@stryker-mutator/vitest-runner", "@stryker-mutator/typescript-checker"],

  // Point at your vitest config if not at project root.
  // vitest: { configFile: "vitest.config.ts" },

  // Files to mutate. Excludes test files, schemas, and generated code.
  mutate: ["src/**/*.ts", "!src/**/*.{test,spec}.ts", "!src/**/*.d.ts", "!src/schemas/**"],

  // TypeScript support.
  checkers: ["typescript"],
  tsconfigFile: "tsconfig.json",

  // Reuse compatible prior results; invalidation follows Stryker's cache rules.
  // Use the full command for independent baselines and after relevant changes.
  incremental: true,
  incrementalFile: ".stryker-tmp/incremental.json",

  // Quality thresholds. Build fails if mutation score drops below break.
  // 80% line coverage with a 40% mutation score means tests observe but don't assert.
  thresholds: {
    high: 80,
    low: 60,
    break: 60,
  },

  // Reporters.
  reporters: ["html", "progress"],
  htmlReporter: { fileName: "reports/mutation/report.html" },

  // Conservative reference budget; tune deliberately for the project/host.
  concurrency: 1,

  // Timeout per mutant in milliseconds.
  timeoutMS: 30000,

  // Ignore temporary Stryker files from git.
  tempDirName: ".stryker-tmp",
};

base.scripts/check-package-manager.mjs:
import { readFileSync } from "node:fs";

// Check the consumer's pin, not a second hard-coded version. No download or shell.
const manifest = JSON.parse(readFileSync(new URL("../package.json", import.meta.url), "utf8"));
const pin = manifest.packageManager;
const actual = (process.env.npm_config_user_agent ?? "").split(" ")[0];

if (typeof pin !== "string" || !pin.startsWith("pnpm@")) {
  process.stderr.write("package.json must declare a pnpm packageManager pin.\n");
  process.exit(1);
}

// Corepack pins may append a +sha... integrity suffix; user agents omit it.
const expected = pin.split("+")[0].replace("@", "/");
if (actual !== expected) {
  process.stderr.write(
    "Use the pnpm version declared in package.json; keep pnpm-lock.yaml frozen.\n",
  );
  process.exit(1);
}

base.src/schemas/example.ts:
import { z } from "zod";

// This protocol rejects unknown fields; other protocols may strip/preserve them.
// A valid role is a shape check, NOT permission to create an admin user.
const CreateUserSchema = z
  .object({
    email: z.string().email(),
    name: z.string().min(1).max(100),
    role: z.enum(["admin", "member", "viewer"]),
    avatarUrl: z.string().url().optional(),
  })
  .strict();

type CreateUserInput = z.infer<typeof CreateUserSchema>;

// Caller must reject null before effects and separately authorize the operation.
// Do not log raw validation errors or echo them into public responses.
function handleCreateUser(rawBody: unknown): CreateUserInput | null {
  const result = CreateUserSchema.safeParse(rawBody);
  return result.success ? result.data : null;
}

// Use the async path when a project's schema has async refinements/transforms.
async function handleCreateUserAsync(rawBody: unknown): Promise<CreateUserInput | null> {
  const result = await CreateUserSchema.safeParseAsync(rawBody);
  return result.success ? result.data : null;
}

export type { CreateUserInput };
export { CreateUserSchema, handleCreateUser, handleCreateUserAsync };

base.src/schemas/example.test.ts:
import { describe, expect, it } from "vitest";
import { CreateUserSchema, handleCreateUser, handleCreateUserAsync } from "./example";

const valid = { email: "user@example.com", name: "Chris", role: "member" };
const invalid = [
  null,
  undefined,
  [],
  "user",
  {},
  { ...valid, email: "invalid" },
  { ...valid, name: "" },
  { ...valid, name: "x".repeat(101) },
  { ...valid, role: "owner" },
  { ...valid, extra: true },
  { ...valid, avatarUrl: "not-a-url" },
  { ...valid, email: 42 },
];

describe("CreateUser boundary", () => {
  it("accepts each declared role without treating it as authorization", () => {
    for (const role of ["admin", "member", "viewer"]) {
      const input = { ...valid, role };
      expect(handleCreateUser(input)).toEqual(input);
    }
  });

  it("preserves optional URLs and both name limits", async () => {
    for (const name of ["x", "x".repeat(100)]) {
      const input = { ...valid, name, avatarUrl: "https://example.com/avatar.png" };
      expect(handleCreateUser(input)).toEqual(input);
      expect(await handleCreateUserAsync(input)).toEqual(input);
    }
  });

  it.each(
    invalid.map((input) => [input]),
  )("rejects invalid input %# in both parser paths", async (input) => {
    expect(CreateUserSchema.safeParse(input).success).toBe(false);
    expect(handleCreateUser(input)).toBeNull();
    expect(await handleCreateUserAsync(input)).toBeNull();
  });

  it("lets a caller stop before effects and does not mutate inputs", () => {
    const accepted: unknown[] = [];
    const receive = (raw: unknown) => {
      const parsed = handleCreateUser(raw);
      if (parsed !== null) accepted.push(parsed);
    };
    const rejected = { ...valid, extra: true };
    const before = structuredClone(rejected);
    receive(rejected);
    expect(rejected).toEqual(before);
    expect(accepted).toEqual([]);
    receive(valid);
    expect(accepted).toEqual([valid]);
    expect(valid).toEqual({ email: "user@example.com", name: "Chris", role: "member" });
  });
});

